use rk3588_boot_support::{DelayUs,Mmio32};use crate::stage12::{pmumcu_wait_idle,PmuMcuError,PMUMCU_STATUS_GATE};
pub const PMUMCU_QUIESCE_GATE_VALUE:u32=0x2000_2000;pub const PMUMCU_CRU_STATUS_ADDR:u64=0xFE03_808C;pub const PMUMCU_RESET_ADDR:u64=0xFD58_2000;pub const PMUMCU_RESET_VALUE:u32=0x0008_0008;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum PmuMcuQuiesceFollowup{None,ReferenceFallback}
pub fn pmumcu_quiesce_reference<I:Mmio32+DelayUs>(io:&mut I,flags:u32,descriptor_valid:bool)->Result<PmuMcuQuiesceFollowup,PmuMcuError>{if flags==0{return Ok(PmuMcuQuiesceFollowup::None)}pmumcu_wait_idle(io)?;io.write32(PMUMCU_STATUS_GATE,PMUMCU_QUIESCE_GATE_VALUE);let v=io.read32(PMUMCU_CRU_STATUS_ADDR);io.write32(PMUMCU_CRU_STATUS_ADDR,v|0x00FF_0000);io.write32(PMUMCU_RESET_ADDR,PMUMCU_RESET_VALUE);Ok(if !descriptor_valid&&flags&2!=0{PmuMcuQuiesceFollowup::ReferenceFallback}else{PmuMcuQuiesceFollowup::None})}
#[cfg(test)]mod tests{use super::*;struct M{cru:u32,n:u8}impl Mmio32 for M{fn read32(&mut self,a:u64)->u32{match a{0xFD7F0A00=>0x2000,PMUMCU_CRU_STATUS_ADDR=>self.cru,_=>0}}fn write32(&mut self,a:u64,v:u32){self.n+=1;if a==PMUMCU_CRU_STATUS_ADDR{self.cru=v}}}impl DelayUs for M{fn delay_us(&mut self,_:u32){}}#[test]fn quiesce(){let mut m=M{cru:0x1234,n:0};assert_eq!(pmumcu_quiesce_reference(&mut m,2,false),Ok(PmuMcuQuiesceFollowup::ReferenceFallback));assert_eq!(m.cru,0x00FF_1234);assert_eq!(m.n,3);}}
